package com.nigson.acceptance.pricing;
import com.nigson.commerce.pricing.*;
import com.nigson.commerce.market.MarketValues;
import com.nigson.shared.events.EventCodec;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
class PricingValuesTest {
 @Test void minorUnitsRejectEvenZeroExtraDecimalsAndBinaryOrExponentForms(){assertThat(PricingValues.minor("1234.56",2)).isEqualByComparingTo("1234.56");assertThat(PricingValues.minor("999999999999999.99",2)).isEqualByComparingTo("999999999999999.99");for(String value:List.of("1.000","1.001","1e2","-1","NaN"," 1","1,00"))assertThatThrownBy(()->PricingValues.minor(value,2)).isInstanceOf(com.nigson.shared.problem.Problem.Failure.class);assertThatThrownBy(()->PricingValues.quantity("0.001",2)).hasMessage("PRICING_RULE_VIOLATION");assertThatThrownBy(()->PricingValues.rounded(new BigDecimal("1000000000000000"),2)).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void inclusiveRoundingConservesEveryMinorUnitAfterDiscount(){var tax=new MarketValues.TaxPolicy("INCLUSIVE",new BigDecimal("0.075"),"SYNTHETIC_NOT_APPROVED");for(int amount=1;amount<=300;amount++)for(int discount=0;discount<=amount;discount++){var before=new BigDecimal(java.math.BigInteger.valueOf(amount),2);var off=new BigDecimal(java.math.BigInteger.valueOf(discount),2);var c=PricingValues.components(BigDecimal.ONE,before,off,tax,2);assertThat(c.subtotal().subtract(c.discount()).add(c.tax())).isEqualByComparingTo(before.subtract(off));assertThat(c.total()).isEqualByComparingTo(before.subtract(off));assertThat(c.discount()).isNotNegative();assertThat(c.tax()).isNotNegative();}}
 @Test void exclusiveAndNoneTaxUseRoundedLineNet(){var c=PricingValues.components(new BigDecimal("0.125"),new BigDecimal("12.34"),new BigDecimal("0.01"),new MarketValues.TaxPolicy("EXCLUSIVE",new BigDecimal("0.075"),"SYNTHETIC_NOT_APPROVED"),2);assertThat(c.subtotal()).isEqualByComparingTo("1.54");assertThat(c.tax()).isEqualByComparingTo("0.11");assertThat(c.total()).isEqualByComparingTo("1.64");assertThatThrownBy(()->PricingValues.components(BigDecimal.ONE,BigDecimal.ONE,new BigDecimal("1.01"),new MarketValues.TaxPolicy("NONE",BigDecimal.ZERO,"SYNTHETIC_NOT_APPROVED"),2)).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void largestRemainderIsExactAndIndependentOfInputOrder(){UUID first=UUID.fromString("00000000-0000-0000-0000-000000000001"),second=UUID.fromString("80000000-0000-0000-0000-000000000001"),last=UUID.fromString("ffffffff-ffff-ffff-ffff-ffffffffffff");var amounts=new LinkedHashMap<UUID,BigDecimal>();amounts.put(last,new BigDecimal("1.00"));amounts.put(second,new BigDecimal("1.00"));amounts.put(first,new BigDecimal("1.00"));var result=PricingValues.allocate(amounts,new BigDecimal("0.02"),2);assertThat(result.get(first)).isEqualByComparingTo("0.01");assertThat(result.get(second)).isEqualByComparingTo("0.01");assertThat(result.get(last)).isEqualByComparingTo("0.00");for(int cents=0;cents<=300;cents++)assertThat(PricingValues.allocate(amounts,new BigDecimal(java.math.BigInteger.valueOf(cents),2),2).values().stream().reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo(new BigDecimal(java.math.BigInteger.valueOf(cents),2));assertThatThrownBy(()->PricingValues.allocate(amounts,new BigDecimal("3.01"),2)).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void ambiguousNumericTiersAndUnknownInputAreRejected(){UUID sku=UUID.randomUUID();String input="{\"code\":\"SYNTHETIC_ONLY\",\"currency\":\"NGN\",\"segment\":\"RETAIL\",\"effectiveFrom\":\"2026-10-10T00:00:00Z\",\"entries\":[{\"skuId\":\""+sku+"\",\"minimumQuantity\":\"1\",\"unitAmount\":\"1.00\"},{\"skuId\":\""+sku+"\",\"minimumQuantity\":\"1.000\",\"unitAmount\":\"2.00\"}]}";assertThatThrownBy(()->PricingValues.input(EventCodec.JSON.readTree(input),true)).hasMessage("PRICING_RULE_VIOLATION");assertThatThrownBy(()->PricingValues.quoteInput(EventCodec.JSON.readTree("{\"cartId\":\""+sku+"\",\"addressId\":\""+sku+"\",\"carrierQuoteId\":\""+sku+"\",\"fee\":\"0\"}"))).hasMessage("VALIDATION_ERROR");}
 @Test void packingUsesActualUnitsAndTareAcrossFullAndRemainderCartons(){UUID sku=UUID.randomUUID();var rule=EventCodec.JSON.readTree("{\"schemaVersion\":1,\"maximumUnitsPerPackage\":\"10\",\"unitWeightKg\":\"0.125\",\"tareWeightKg\":\"0.25\",\"lengthCm\":\"10\",\"widthCm\":\"20\",\"heightCm\":\"30\"}");var parcels=CarrierPacking.pack(List.of(new CarrierPacking.Item(sku,new BigDecimal("23"),0,rule)));assertThat(parcels).hasSize(3);assertThat(parcels.getFirst().weightKg()).isEqualTo("1.5");assertThat(parcels.getLast().quantity()).isEqualTo("3");assertThat(parcels.getLast().weightKg()).isEqualTo("0.625");assertThatThrownBy(()->CarrierPacking.pack(List.of(new CarrierPacking.Item(sku,new BigDecimal("1001"),0,rule)))).hasMessage("PRICING_RULE_VIOLATION");assertThatThrownBy(()->CarrierPacking.pack(List.of(new CarrierPacking.Item(sku,BigDecimal.ONE,0,null)))).hasMessage("PRICING_RULE_VIOLATION");}
 @Test void productionProviderPolicyCannotDefaultToMockOrMissingApprovals(){var clock=java.time.Clock.systemUTC();assertThatThrownBy(()->new PricingProviders(true,"prod","MOCK","SYNTHETIC_ONLY","SYNTHETIC_ONLY",clock.instant().plusSeconds(300),clock,"1".repeat(64))).hasMessage("PRICING_PROVIDER_APPROVAL_REQUIRED");assertThatThrownBy(()->new PricingProviders(true,"test","MOCK","","",clock.instant().plusSeconds(300),clock,"1".repeat(64))).hasMessage("PRICING_PROVIDER_APPROVAL_REQUIRED");var disabled=new PricingProviders(false,"test","","","",null,clock,"1".repeat(64));assertThatThrownBy(()->disabled.require("MOCK")).hasMessage("FEATURE_DISABLED");}

 @Test void masterArrayCapAcceptsHundredEntriesAndRejectsHundredAndOne(){UUID sku=UUID.randomUUID();var entries=EventCodec.JSON.createArrayNode();for(int quantity=1;quantity<=100;quantity++)entries.add(EventCodec.JSON.valueToTree(Map.of("skuId",sku,"minimumQuantity",Integer.toString(quantity),"unitAmount","1.00")));var input=EventCodec.JSON.valueToTree(Map.of("code","Synthetic reviewed book","currency","NGN","segment","RETAIL","effectiveFrom","2026-10-10T00:00:00Z","entries",entries));assertThat(PricingValues.input(input,true).entries()).hasSize(100);entries.add(EventCodec.JSON.valueToTree(Map.of("skuId",sku,"minimumQuantity","101","unitAmount","1.00")));((tools.jackson.databind.node.ObjectNode)input).set("entries",entries);assertThatThrownBy(()->PricingValues.input(input,true)).hasMessage("VALIDATION_ERROR");}

}
